preview_tmpl:
{{@if(it.content?.length > 0)}}
  {{@each(it.content) => val, index}}
    {{@if(index < 3)}}
      {{@if(val.component === 'sb-headline')}}
        {{@if(!!val.content?.length)}}
          {{@if(!Array.isArray(val.content))}}
            <div><i>{{val.content}}</i></div>
          {{/if}}
        {{/if}}
      {{#elif(val.component === 'sb-text')}}
        {{@if(val.content?.content?.[0]?.content?.[0]?.text)}}
          <div><i>{{val.content.content[0].content[0].text}}</i></div>
        {{/if}}
      {{#elif(val.component === 'sb-richtext')}}
        {{@if(val.content?.content?.[0]?.content?.[0]?.text)}}
          <div><i>{{val.content.content[0].content[0].text}}</i></div>
        {{/if}}
      {{#elif(val.component === 'sb-list')}}
        <div class="font-regular">List component</div>
      {{#elif(val.component === 'sb-button-group')}}
        <div class="font-regular">Button group</div>
      {{#elif(val.component === 'sb-tag')}}
        {{@if(val.text)}}
          <div class="font-bold">{{val.text}}</div>
        {{/if}}
      {{#elif(val.component === 'sb-divider')}}
        <div class="font-regular">---</div>
      {{/if}}

      {{@if(index < 2)}}
        {{@if(index !== it.content.length - 1)}}
          <div style="margin: 4px 0;"></div>
        {{/if}}
      {{/if}}
    {{/if}}
  {{/each}}

  {{@if(it.content.length > 3)}}
    <div class="font-light">+ {{it.content.length - 3}} more items</div>
  {{/if}}
{{/if}}
